  for (size_t i = 0; i < loop; i++) {
    pSource8[i] ^= mask8;
  }

  //
  // Apply mask to remaining data.
  //
  length %= 8;
  source += 8 * loop;

  for (uint8_t i = 0; i < length; i++) {
    source[i] ^= maskAlignedArray[i];
  }

